return ['domain'=>'publishpress-hub% 10 == 0) ? 2 : 3)));% 10 == 0) ? 2: 3)));','plural-forms'=>'nplurals=4; plural=(n == 1 ? 0 : (n == 2 ? 1 : ((n > 10 && n % 10 == 0) ? 2 : 3)));','language'=>'he_IL','project-id-version'=>'PublishPress Hub 1.0.4-beta.3','pot-creation-date'=>'2026-04-14T19:28:02+00:00','po-revision-date'=>'2026-06-01 20:26+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Hub'=>'פאבלישפרס הוב','Centralized management hub for all PublishPress plugins - install, update, and manage licenses from one dashboard.'=>'מרכז ניהול מרכזי לכל תוספי PublishPress - התקנה, עדכון וניהול רישיונות מלוח בקרה אחד.','PublishPress'=>'פאבלישפרס','https://publishpress.com'=>'https://publishpress.com','Please wait while we load the components showcase...'=>'אנא המתן בעוד אנו טוענים את תצוגת הרכיבים...','Please wait while we load the plugins dashboard...'=>'אנא המתן בעוד אנו טוענים את לוח המחוונים של התוספים...','Settings'=>'הגדרות','Please wait while we load the settings page...'=>'אנא המתן בעוד אנו טוענים את דף ההגדרות...','You do not have sufficient permissions to access this page.'=>'אין לך מספיק הרשאות לגשת לדף זה.','Welcome'=>'ברוך הבא','Please wait while we load the welcome page...'=>'אנא המתן בעוד אנו טוענים את דף הברוך הבא...','Warning: The license for %1$s has expired. %2$s'=>'אזהרה: הרישיון עבור %1$s פג תוקף. %2$s','Manage licenses'=>'נהל רישיונות','Warning: %1$d plugin(s) have expired licenses: %2$s. %3$s'=>'אזהרה: ל-%1$d תוסף(ים) יש רישיונות פגי תוקף: %2$s. %3$s','Object must be loaded before initializing.'=>'האובייקט חייב להיות טעון לפני אתחול.','No license key found'=>'לא נמצא מפתח רישיון','Free plugin not set for plugin family: %s'=>'תוסף חינמי לא מוגדר למשפחת תוספים: %s','Pro plugin not set for plugin family: %s'=>'תוסף פרו לא מוגדר למשפחת תוספים: %s','License activation error. Please try again later or contact support for help.'=>'שגיאת הפעלת רישיון. אנא נסה שוב מאוחר יותר או פנה לתמיכה לעזרה.','License deactivation error. Please try again later or contact support for help.'=>'שגיאת השבתת רישיון. אנא נסה שוב מאוחר יותר או פנה לתמיכה לעזרה.','This license is currently disabled. Please contact support for help.'=>'רשיון זה מושבת כרגע. אנא פנה לתמיכה לעזרה.','This license has expired. Please contact support to renew it.'=>'רשיון זה פג תוקף. אנא פנה לתמיכה כדי לחדש אותו.','This license key is not authorized for this plugin. Please verify your license key or contact support for help.'=>'מפתח הרישיון הזה אינו מאושר עבור תוסף זה. אנא ודא שמפתח הרישיון שלך נכון או פנה לתמיכה לעזרה.','This license cannot be used for this plugin. Please contact support for help.'=>'רישיון זה אינו יכול לשמש עבור תוסף זה. אנא פנה לתמיכה לעזרה.','This license does not match the plugin you are trying to activate. Please contact support for assistance.'=>'הרישיון הזה אינו תואם לתוסף שאתה מנסה להפעיל. אנא פנה לתמיכה לעזרה.','License key does not match our records. Please contact support for assistance.'=>'מפתח הרישיון אינו תואם לרשומות שלנו. אנא פנה לתמיכה לעזרה.','No license key provided. Please enter a valid license key.'=>'לא סופק מפתח רשיון. אנא הכנס מפתח רשיון תקף.','Your site URL is required to activate the license. Please enter a valid site URL to continue.'=>'כתובת ה-URL של האתר שלך נדרשת כדי להפעיל את הרישיון. אנא הזן כתובת URL תקפה של האתר כדי להמשיך.','License activation limit reached. Please contact support to upgrade or deactivate on another site.'=>'הגעת למגבלת הפעלת הרישיון. אנא פנה לתמיכה כדי לשדרג או להשבית באתר אחר.','This license cannot be activated. Please contact support for help.'=>'רשיון זה אינו יכול להיות מופעל. אנא פנה לתמיכה לעזרה.','License server error. Please try again later or contact support for help.'=>'שגיאת שרת הרשיון. אנא נסה שוב מאוחר יותר או פנה לתמיכה לעזרה.','The license server returned an invalid response. Please try again later or contact support for help.'=>'שרת הרישיונות החזיר תגובה לא חוקית. אנא נסה שוב מאוחר יותר או פנה לתמיכה לעזרה.','This license is inactive for this site. Please contact support for help.'=>'רשיון זה אינו פעיל באתר זה. אנא פנה לתמיכה לעזרה.','Plugin activation failed. Please try again later or contact support for help.'=>'הפעלת התוסף נכשלה. אנא נסה שוב מאוחר יותר או פנה לתמיכה לעזרה.','This action is not possible because the plugin is already installed.'=>'פעולה זו אינה אפשרית מכיוון שהפלאגין כבר מותקן.','Plugin deactivation failed. Please try again later or contact support for help.'=>'השבתת התוסף נכשלה. אנא נסה שוב מאוחר יותר או פנה לתמיכה לעזרה.','Plugin family not found. Please contact support for help.'=>'משפחת הפלאגינים לא נמצאה. אנא פנה לתמיכה לעזרה.','This action is not possible because both free and pro versions are installed. Please uninstall one version to continue.'=>'פעולה זו אינה אפשרית מכיוון ששני גרסאות חינמיות ומקצועיות מותקנות. אנא הסר אחת מהגרסאות כדי להמשיך.','Plugin installation failed. Please contact support for help.'=>'התקנת פלאגין נכשלה. אנא פנה לתמיכה לעזרה.','This action is not possible because the plugin is not activated. Please activate the plugin and try again.'=>'פעולה זו אינה אפשרית מכיוון שהתוסף אינו מופעל. אנא הפעל את התוסף ונסה שוב.','Plugin not found in our available plugins list. Please contact support for help.'=>'התוסף לא נמצא ברשימת התוספים הזמינים שלנו. אנא פנה לתמיכה לעזרה.','This action is not possible because the plugin is not installed. Please install the plugin and try again.'=>'פעולה זו אינה אפשרית מכיוון שהתוסף אינו מותקן. אנא התקן את התוסף ונסה שוב.','Unknown license server error. Please try again later or contact support for help.'=>'שגיאת שרת רישיונות לא ידועה. אנא נסה שוב מאוחר יותר או פנה לתמיכה לעזרה.','Define tasks that authors must complete before publishing.'=>'הגדר משימות שעל הכותבים להשלים לפני הפרסום.','Control who can edit and view your content.'=>'שלוט מי יכול לערוך ולראות את התוכן שלך.','Create, manage and display authors for your content.'=>'צור, נהל והצג כותבים לתוכן שלך.','All the tools you need to improve the block editor.'=>'כל הכלים שאתה צריך כדי לשפר את עורך הבלוקים.','Control your admin area and user roles.'=>'שלוט באזור הניהול שלך ותפקידי המשתמשים.','Schedule changes to your posts.'=>'תזמן שינויים לפוסטים שלך.','Organize, schedule, and plan your publishing.'=>'ארגן, תזמן ותכנן את הפרסום שלך.','Approve and schedule new versions to your published posts.'=>'אשר ותזמן גרסאות חדשות לפוסטים שלך שפורסמו.','Organize your posts into issues or series.'=>'ארגן את הפוסטים שלך למספרים או סדרות.','Create custom URLs for your posts and external links.'=>'צור כתובות URL מותאמות אישית לפוסטים ולקישורים חיצוניים.','Create custom statuses and publishing workflows.'=>'צור סטטוסים מותאמים אישית וזרימות עבודה לפרסום.','Dependency "%s" not found in container.'=>'תלות "%s" לא נמצאה במיכל.','Error validating license: %s'=>'שגיאה באימות רישוי: %s','Error getting license info: %s'=>'שגיאה בהשגת מידע רישוי: %s','Too many requests. Please try again later.'=>'יותר מדי בקשות. אנא נסה שוב מאוחר יותר.','An error occurred while processing your request.'=>'אירעה שגיאה בעת עיבוד הבקשה שלך.','Template not found: %s'=>'תבנית לא נמצאה: %s','Path cannot be empty'=>'הנתיב אינו יכול להיות ריק','File extension cannot be empty'=>'סוג הקובץ אינו יכול להיות ריק','Invalid file path: null byte detected'=>'נתיב קובץ לא חוקי: זיהוי בייט null','Invalid file path: directory traversal detected'=>'נתיב קובץ לא חוקי: זיהוי חציית תיקיות','Invalid file path: parent directory does not exist: %s'=>'נתיב קובץ לא חוקי: תיק הורה אינו קיים: %s','Invalid file path: unable to resolve path'=>'נתיב קובץ לא חוקי: לא ניתן לפתור את הנתיב','Invalid file path: operation not allowed outside permitted directories'=>'נתיב קובץ לא חוקי: פעולה אינה מותרת מחוץ לתיקיות המותרות','Invalid download URL provided'=>'כתובת ה-URL להורדה שסיפקת אינה חוקית','Download URL must use HTTP or HTTPS protocol'=>'כתובת ה-URL להורדה חייבת להשתמש בפרוטוקול HTTP או HTTPS','Download URL is not from an allowed domain: %s'=>'כתובת ה-URL להורדה אינה מהדומיין המותר: %s','Download URL failed WordPress validation'=>'כתובת ה-URL